from collections import defaultdict, deque

def resolve_dag_order(tasks: list[str], dependencies: dict[str, list[str]]) -> dict:
    """Computes valid execution order and cycle detection for task DAGs using Kahn's algorithm."""
    in_degree = {t: 0 for t in tasks}
    adj = defaultdict(list)

    for t, parents in dependencies.items():
        if t in in_degree:
            for p in parents:
                adj[p].append(t)
                in_degree[t] = in_degree.get(t, 0) + 1

    queue = deque([t for t in tasks if in_degree[t] == 0])
    order = []

    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    has_cycle = len(order) != len(tasks)
    unresolved = [t for t in tasks if t not in order]

    return {
        "has_cycle": has_cycle,
        "execution_order": order if not has_cycle else [],
        "unresolved_tasks": unresolved
    }
